def transform(grid):
    n = len(grid[0])
    center = next(i for i, x in enumerate(grid[0]) if x != 0)
    marker = grid[0][center]
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        left, right = max(0, center - r), min(n - 1, center + r)
        for c in range(left, right + 1):
            if c == center - r or c == center + r:
                out[r][c] = marker
            elif r >= 3 and (c - r - center) % 4 == 0:
                out[r][c] = 1
    return out
